INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Section 501(h) expenditure election definition
(3, 'Tax-Exempt Organizations', 'What does the Section 501(h) election provide for eligible 501(c)(3) organizations?', '["Specific dollar thresholds for permissible lobbying expenditures", "An exemption from filing Form 990 annually", "Permission to engage in political campaign activity", "A reduced excise tax rate on net investment income"]'::jsonb, 0, 'Under IRC Section 501(h), eligible 501(c)(3) organizations may elect to use specific dollar thresholds (the expenditure test) to measure permissible lobbying activity, replacing the vague ''substantial part'' standard. The 501(h) election provides measurable spending limits based on exempt purpose expenditures. This election does not permit political campaign activity, which remains absolutely prohibited under Section 501(c)(3).', 'easy', 1),

-- Q2: medium / L3 — Form 990-PF required for all private foundations regardless of size
(3, 'Tax-Exempt Organizations', 'Hope Family Foundation, a small private foundation, has gross receipts of $35,000 and total assets of $180,000 for 2025. The foundation''s accountant suggests filing Form 990-EZ because the organization meets the simplified filing thresholds. Which form must the foundation actually file?', '["Form 990-EZ, because gross receipts are below $200,000", "Form 990-PF, because all private foundations must file this form regardless of size", "Form 990-N, because gross receipts are below $50,000", "Form 990, because total assets exceed $100,000"]'::jsonb, 1, 'Under IRS filing requirements, all private foundations must file Form 990-PF regardless of gross receipts or total assets. The Form 990-EZ and 990-N thresholds apply only to public charities and other exempt organizations, not to private foundations. The accountant''s suggestion to file Form 990-EZ is incorrect because the foundation''s private foundation classification, not its size, determines the required form.', 'medium', 3),

-- Q3: medium / L2 — One-third support test for public charity (Section 509(a)(1))
(3, 'Tax-Exempt Organizations', 'Riverdale Community Alliance receives $400,000 from government grants, $150,000 from public donations, and $50,000 from investment income in 2025. Its total support is $600,000. Under Section 509(a)(1), does the organization meet the one-third support test for public charity classification?', '["No, because investment income counts against the public support fraction", "No, because government grants do not qualify as public support", "Yes, because public and government support ($550,000) exceeds one-third of total support", "Yes, because any organization receiving government grants automatically qualifies"]'::jsonb, 2, 'Under IRC Section 509(a)(1), an organization qualifies as a public charity if it receives a substantial part of support from the general public or government. Here, public and government support totals $550,000 out of $600,000 (91.7%), far exceeding the one-third threshold. Investment income is not public support, but it is simply excluded from the numerator rather than disqualifying the organization. Government grants do count as public support under this test.', 'medium', 2),

-- Q4: easy / L1 — Dissolution clause requirement
(3, 'Tax-Exempt Organizations', 'What must a 501(c)(3) organization''s governing documents provide regarding asset distribution upon dissolution?', '["Assets must be distributed equally among the organization''s members", "Assets must be returned to the original donors or their heirs", "Assets must be sold at fair market value on the open market", "Assets must be distributed to another exempt organization or to the government"]'::jsonb, 3, 'Under IRC Section 501(c)(3), the organizational test requires a dissolution clause providing that upon dissolution, the organization''s assets will be distributed to another exempt organization or to the government. This prevents private individuals from benefiting when a tax-exempt entity ceases operations. Distributing assets to members or returning them to donors would violate this requirement and jeopardize exempt status.', 'easy', 1),

-- Q5: medium / L2 — Personal property rents and the 10% incidental threshold
(3, 'Tax-Exempt Organizations', 'Lakewood Education Center, a 501(c)(3), leases office space and furniture to a tenant under a single lease for $10,000 per month. Of this amount, $8,000 is allocable to real property and $2,000 to personal property (furniture), representing 20% of total rent. How is the personal property portion treated for UBIT purposes?', '["The $2,000 personal property rent is included in unrelated business income because it exceeds the 10% incidental threshold", "All $10,000 in rent is excluded because real property rents are always exempt from UBIT", "All $10,000 in rent is included because any personal property makes the entire lease taxable", "The $2,000 personal property rent is excluded because all rental income from leases is passive income"]'::jsonb, 0, 'Under IRC Section 512(b)(3), rents from real property are generally excluded from UBIT, but rents attributable to personal property are included unless they are incidental (less than 10% of total rents under the lease). Here, personal property represents 20% of total rent, exceeding the 10% threshold, so the $2,000 personal property portion is taxable. The real property portion ($8,000) remains excluded. The presence of personal property does not automatically make all rent taxable.', 'medium', 2),

-- Q6: medium / L2 — Controlled entity payments from 80%+ subsidiary
(3, 'Tax-Exempt Organizations', 'Bright Horizons Foundation, a 501(c)(3), owns 85% of Bright Horizons Publishing, Inc. The subsidiary pays $120,000 in annual rent to the foundation at fair market value for office space. How is this rental income treated for UBIT purposes under Section 512?', '["The rent is fully excluded as passive real property rental income", "The rent is treated as unrelated business income because it is received from a controlled subsidiary", "Only 85% of the rent is treated as unrelated business income", "The rent is excluded because it was paid at fair market value"]'::jsonb, 1, 'Under IRC Section 512(b)(13), rent, interest, or royalties received from a controlled entity (80% or more ownership) are treated as unrelated business income to the extent they reduce the subsidiary''s taxable income. Since Bright Horizons Foundation owns 85% of the subsidiary, the entity is controlled, and the $120,000 rent is included in UBIT. The passive income exclusion does not apply to payments from controlled subsidiaries, regardless of whether the rent is at fair market value.', 'medium', 2),

-- Q7: medium / L3 — Section 4945 taxable expenditure for lobbying by private foundation
(3, 'Tax-Exempt Organizations', 'Marshall Foundation, a private foundation, spends $25,000 on advertisements opposing a ballot initiative to increase property taxes. The board believes this qualifies as grassroots civic engagement rather than lobbying. How does Section 4945 classify this expenditure?', '["It is permissible because opposing a ballot initiative is not considered lobbying", "It is subject to the self-dealing rules under Section 4941", "It is a taxable expenditure subject to a 20% initial excise tax under Section 4945", "It is permissible if the foundation has made a Section 501(h) election"]'::jsonb, 2, 'Under IRC Section 4945, private foundations are prohibited from making taxable expenditures, which include amounts spent to influence legislation (lobbying). Opposing a ballot initiative is considered an attempt to influence legislation. The initial excise tax is 20% of the expenditure ($5,000). Private foundations cannot make the Section 501(h) election, which is available only to public charities. The board''s characterization as ''civic engagement'' does not change the legal classification.', 'medium', 3),

-- Q8: hard / L4 — Private benefit doctrine vs private inurement distinction
(3, 'Tax-Exempt Organizations', 'Greenleaf Environmental Trust, a 501(c)(3), contracts with an outside consulting firm owned by an individual with no relationship to the organization''s officers, directors, or key employees. The contract price of $300,000 significantly exceeds the $150,000 fair market value of the services. Analyze how the private benefit and private inurement doctrines apply to this arrangement.', '["This is private inurement because the contract benefits a specific individual at the expense of the organization", "Neither doctrine applies because the consultant is not a disqualified person and the board approved the contract", "This violates only the private inurement prohibition because the payment exceeds fair market value", "This violates the private benefit doctrine but not the private inurement prohibition because the consultant is not an insider"]'::jsonb, 3, 'Under IRC Section 501(c)(3), the private benefit doctrine prohibits more-than-incidental benefit to any private individual, whether or not they are an insider. Private inurement applies only when net earnings benefit insiders (private shareholders or individuals with a personal interest in the organization). Here, the consultant is not an insider, so private inurement does not apply. However, paying $300,000 for $150,000 worth of services provides substantial private benefit to an outsider, violating the operational test regardless of board approval.', 'hard', 4),

-- Q9: medium / L3 — Filing deadline for fiscal-year organization
(3, 'Tax-Exempt Organizations', 'Pacific Health Alliance, a 501(c)(3) public charity, has a fiscal year ending September 30. The organization needs to determine its Form 990 filing deadline. Applying the standard filing rule, what is the deadline for the fiscal year ending September 30, 2025?', '["February 15, 2026, which is the 15th day of the 5th month after the fiscal year ends", "March 15, 2026, which is the 15th day of the 6th month after the fiscal year ends", "January 15, 2026, which is the 15th day of the 4th month after the fiscal year ends", "April 15, 2026, which aligns with the individual tax return deadline"]'::jsonb, 0, 'Under IRS filing rules, Form 990 is due on the 15th day of the 5th month after the organization''s tax year ends. For a September 30 fiscal year-end, the 5th month after is February, making the deadline February 15, 2026. This mirrors the general rule for calendar-year organizations, which file by May 15. Extensions of up to 6 months are available using Form 8868, which would extend the deadline to August 15, 2026.', 'medium', 3),

-- Q10: easy / L1 — Convenience exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Under Section 513, what is the convenience exclusion from unrelated business income tax?', '["An exclusion for activities generating less than $1,000 in gross income", "An exclusion for activities conducted primarily for the convenience of members, students, patients, or employees", "An exclusion for activities that use only donated merchandise", "An exclusion for activities performed entirely by volunteers"]'::jsonb, 1, 'Under IRC Section 513(a)(2), an activity conducted primarily for the convenience of an organization''s members, students, patients, or employees is excluded from UBIT, even if it otherwise meets the three-part test. A common example is a hospital cafeteria serving staff and patients. This is distinct from the volunteer labor exclusion (substantially all work by volunteers) and the donated merchandise exclusion (substantially all goods donated).', 'easy', 1),

-- Q11: hard / L4 — Section 4958 cumulative 200% additional tax analysis
(3, 'Tax-Exempt Organizations', 'Dr. Parker, the CEO of Community Wellness Foundation (a 501(c)(3)), receives $750,000 in total compensation when comparability data shows $250,000 is reasonable. The IRS identifies a $500,000 excess benefit under Section 4958. Dr. Parker fails to return the excess benefit within the correction period. Evaluate the total excise tax liability Dr. Parker faces.', '["$125,000, consisting of a 25% initial tax on the $500,000 excess benefit", "$500,000, consisting only of a 200% additional tax because it replaces the initial tax", "$1,125,000, consisting of a 25% initial tax ($125,000) plus a 200% additional tax ($1,000,000) on the uncorrected excess benefit", "$625,000, consisting of a 25% initial tax ($125,000) plus a 100% penalty ($500,000) for willful noncompliance"]'::jsonb, 2, 'Under IRC Section 4958, the initial excise tax on a disqualified person is 25% of the excess benefit ($500,000 x 25% = $125,000). If the excess benefit is not corrected within the taxable period, an additional 200% tax applies ($500,000 x 200% = $1,000,000). These taxes are cumulative, totaling $1,125,000. The additional tax supplements rather than replaces the initial tax. Correction requires the disqualified person to undo the excess benefit to the extent possible.', 'hard', 4),

-- Q12: hard / L4 — Section 4943 combined holdings with disqualified persons
(3, 'Tax-Exempt Organizations', 'Carter Private Foundation owns 12% of the voting stock of Apex Industries. The foundation''s creator, a disqualified person, owns 15% personally. An unrelated investor offers to sell the foundation an additional 5% stake. Evaluate the excess business holdings implications under Section 4943 if the foundation acquires the additional shares.', '["The acquisition is permissible because the foundation would hold only 17%, below the 20% threshold", "The acquisition would create excess holdings because the foundation alone would exceed 20%", "The acquisition is permissible because purchases from unrelated parties are exempt from the excess business holdings rules", "The acquisition would create excess holdings because combined ownership (foundation 17% plus disqualified person 15% equals 32%) exceeds the 20% permitted holding"]'::jsonb, 3, 'Under IRC Section 4943, the combined holdings of a private foundation and its disqualified persons generally cannot exceed 20% of the voting stock of a business enterprise. After the acquisition, the foundation would hold 17% and the disqualified person holds 15%, totaling 32%, which exceeds the 20% limit by 12%. A 10% initial excise tax applies to excess business holdings. The test considers combined ownership, not the foundation''s holdings alone.', 'hard', 4),

-- Q13: medium / L2 — Schedule B confidentiality
(3, 'Tax-Exempt Organizations', 'Sunrise Literacy Project, a 501(c)(3), files its annual Form 990 with the IRS. A journalist requests a copy of the organization''s complete Form 990, including Schedule B (Schedule of Contributors). What must the organization provide?', '["The Form 990 without Schedule B, because contributor information is not required to be publicly disclosed", "The complete Form 990 including Schedule B, because all schedules are public record", "Only the first two pages of Form 990, because detailed financial data is confidential", "Nothing, because 501(c)(3) organizations are exempt from public disclosure requirements"]'::jsonb, 0, 'Under IRC Section 6104, tax-exempt organizations must make their Form 990 available for public inspection, but Schedule B (Schedule of Contributors) is specifically excluded from the public disclosure requirement. Contributor names and addresses remain confidential. The organization must provide the complete Form 990 with all other schedules but may redact Schedule B. This protects donor privacy while maintaining organizational transparency.', 'medium', 2),

-- Q14: easy / L2 — Supporting organization (Section 509(a)(3))
(3, 'Tax-Exempt Organizations', 'Metro Arts Alliance exists solely to raise funds and provide administrative support for three public art museums, all of which are 501(c)(3) public charities. Under what classification does Metro Arts Alliance most likely qualify?', '["Private foundation, because it does not directly serve the public", "Supporting organization under Section 509(a)(3), because it is operated exclusively to support public charities", "Private operating foundation, because it conducts its own programs", "Social welfare organization under Section 501(c)(4)"]'::jsonb, 1, 'Under IRC Section 509(a)(3), an organization that is organized and operated exclusively to support one or more public charities qualifies as a supporting organization and is itself classified as a public charity. Metro Arts Alliance meets this test because it exists solely to support three public art museums. This classification avoids the additional restrictions and excise taxes that apply to private foundations.', 'easy', 2),

-- Q15: medium / L2 — Research exclusion requirements
(3, 'Tax-Exempt Organizations', 'Northern Plains University, a 501(c)(3) institution, operates a research laboratory that conducts studies under contract with a private pharmaceutical company. The research results are proprietary and not publicly available. Annual revenue from these contracts is $750,000. Is this research income excluded from UBIT?', '["Yes, because all research conducted by a university is excluded from UBIT", "Yes, because research income is automatically classified as passive income", "No, because the research exclusion requires that results be freely available to the public or that research be conducted for the government", "No, because $750,000 exceeds the $1,000 specific deduction threshold"]'::jsonb, 2, 'Under IRC Section 512(b)(7)-(9), research income is excluded from UBIT only if the research is performed for the U.S. government or a state, performed by a college or university with results freely available to the general public, or performed by a hospital. Proprietary research for a private company with restricted results does not qualify. The fact that a university conducts the research does not automatically create an exclusion — the results must be publicly available.', 'medium', 2),

-- Q16: easy / L1 — Bingo games exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Under Section 513(f), when is income from bingo games excluded from unrelated business income tax?', '["When bingo games are conducted fewer than four times per year", "When bingo game proceeds are used exclusively for charitable purposes", "When bingo games are conducted in a state that prohibits all gambling", "When bingo is legal and commercial bingo is not ordinarily carried on in the jurisdiction"]'::jsonb, 3, 'Under IRC Section 513(f), income from bingo games is excluded from UBIT if the game is legal under state and local law and commercial bingo operations are not ordinarily carried on in the same jurisdiction. This prevents tax-exempt organizations from competing directly with commercial bingo operators. The exclusion is based on competitive conditions in the jurisdiction, not on the frequency of games or the use of proceeds.', 'easy', 1),

-- Q17: medium / L2 — NOL deduction rules for UBIT
(3, 'Tax-Exempt Organizations', 'Eastside Community Foundation, a 501(c)(3), has unrelated business income of $40,000 and directly connected expenses of $55,000 in 2025, resulting in a $15,000 net loss. In 2026, the foundation earns $30,000 in unrelated business income with $10,000 in expenses. How does the 2025 loss affect the 2026 UBIT computation?', '["The $15,000 NOL carries forward and reduces 2026 unrelated business taxable income from $20,000 to $5,000", "The NOL cannot be used because tax-exempt organizations are not permitted NOL deductions", "The NOL carries forward but can only offset 50% of 2026 unrelated business income", "The $15,000 loss is applied against the foundation''s investment income instead of future UBI"]'::jsonb, 0, 'Under IRC Section 512(b)(6), tax-exempt organizations may claim a net operating loss deduction, but the NOL is computed using only unrelated business income items. The 2025 loss of $15,000 carries forward to 2026. In 2026, UBI is $30,000 minus $10,000 expenses = $20,000. The $15,000 NOL carryforward reduces this to $5,000, before the $1,000 specific deduction. The NOL cannot offset investment income or other exempt function revenue.', 'medium', 2),

-- Q18: easy / L1 — Form 990 vs Form 990-EZ filing size thresholds
(3, 'Tax-Exempt Organizations', 'What are the filing thresholds that determine whether a public charity files Form 990 versus Form 990-EZ?', '["Form 990 is required for organizations with 50 or more employees", "Form 990 is required when gross receipts are $200,000 or more, or total assets are $500,000 or more", "Form 990 is required only when an organization has unrelated business income", "Form 990-EZ may be filed by any organization regardless of size"]'::jsonb, 1, 'Under IRS filing rules, an exempt organization must file Form 990 if its gross receipts are $200,000 or more OR its total assets are $500,000 or more. Organizations below both thresholds may file the simplified Form 990-EZ. Organizations with gross receipts of $50,000 or less may file Form 990-N (e-Postcard). The threshold is based on financial size, not employee count or income type.', 'easy', 1),

-- Q19: medium / L3 — Section 4944 jeopardizing investment analysis
(3, 'Tax-Exempt Organizations', 'Heritage Arts Foundation, a private foundation, invests $500,000 in a speculative cryptocurrency fund with no guaranteed return and high volatility. The investment committee documents that the fund aligns with the foundation''s risk tolerance. Applying Section 4944, how should this investment be evaluated?', '["The investment is permissible because the investment committee documented its reasoning", "The investment is automatically prohibited because cryptocurrency is not a traditional asset class", "The investment may constitute a jeopardizing investment subject to a 10% initial excise tax if it risks the foundation''s ability to carry out exempt purposes", "The investment is permissible because the foundation has discretion over its entire portfolio"]'::jsonb, 2, 'Under IRC Section 4944, a jeopardizing investment is one that shows a lack of reasonable business care and prudence in providing for the foundation''s short- and long-term financial needs. A highly speculative cryptocurrency investment with no guaranteed return may jeopardize the foundation''s ability to fulfill its exempt purposes. Documentation alone does not insulate the foundation from liability; the investment must be objectively prudent. The initial excise tax is 10% of the amount invested.', 'medium', 3),

-- Q20: medium / L3 — Section 4941 foundation manager tax (5%) computation
(3, 'Tax-Exempt Organizations', 'Davidson Family Foundation, a private foundation, leases office space from its founder for $8,000 per month at fair market value. The executive director, who serves on the board, reviews the lease and approves it knowing that leases with disqualified persons are prohibited. Apply Section 4941 to determine the foundation manager''s excise tax liability.', '["No tax, because the lease is at fair market value", "10% of the lease payments for the year ($9,600)", "25% of the lease payments, treating the manager as a disqualified person", "5% of the lease payments for the year ($4,800), because the manager knowingly participated in the self-dealing transaction"]'::jsonb, 3, 'Under IRC Section 4941, any lease between a private foundation and a disqualified person (including the founder) is self-dealing regardless of whether the rent is at fair market value. The initial tax on the self-dealer (founder) is 10% of the amount involved. A foundation manager who knowingly participates faces a 5% tax. Annual lease payments total $96,000, so the manager''s tax is 5% x $96,000 = $4,800. Fair market value does not excuse the transaction.', 'medium', 3),

-- Q21: easy / L1 — Exempt purposes recognized under 501(c)(3)
(3, 'Tax-Exempt Organizations', 'Which of the following is an exempt purpose recognized under Section 501(c)(3)?', '["Prevention of cruelty to children or animals", "Promotion of political candidates for public office", "Operation of social clubs for members'' recreation", "Advancement of commercial trade interests"]'::jsonb, 0, 'Under IRC Section 501(c)(3), exempt purposes include religious, charitable, scientific, testing for public safety, literary, educational, fostering national or international amateur sports competition, and prevention of cruelty to children or animals. Political campaign activity is absolutely prohibited. Social clubs fall under Section 501(c)(7), and trade associations under Section 501(c)(6), so neither qualifies under 501(c)(3).', 'easy', 1),

-- Q22: hard / L3 — Debt/basis ratio computation for debt-financed property
(3, 'Tax-Exempt Organizations', 'Harmony Education Trust, a 501(c)(3), purchases a commercial building for $1,200,000, financing $800,000 with a mortgage. The building generates $120,000 in annual rental income with $20,000 in deductible expenses. The average acquisition indebtedness is $600,000 and the average adjusted basis is $1,000,000. Calculate the unrelated debt-financed income subject to UBIT.', '["$120,000, because all income from debt-financed property is fully taxable", "$60,000, calculated as the debt/basis percentage (60%) applied to net income of $100,000", "$100,000, because the full net income is taxable after deducting expenses", "$72,000, calculated as 60% of the gross rental income"]'::jsonb, 1, 'Under IRC Section 514, income from debt-financed property is subject to UBIT in proportion to the debt/basis ratio. The ratio is average acquisition indebtedness ($600,000) divided by average adjusted basis ($1,000,000) = 60%. This percentage applies to net income: $120,000 gross income minus $20,000 expenses = $100,000 x 60% = $60,000. The ratio uses average indebtedness and average basis, not the original purchase terms, and applies to net income rather than gross income.', 'hard', 3),

-- Q23: medium / L3 — Section 4942 additional 100% tax if not corrected
(3, 'Tax-Exempt Organizations', 'Sterling Charitable Foundation, a private foundation with non-charitable-use assets of $8,000,000, distributes only $200,000 for charitable purposes instead of the required 5% minimum. The foundation does not correct the $200,000 underdistribution during the taxable period. What additional tax applies under Section 4942?', '["A second 30% tax on the $200,000 underdistribution ($60,000)", "An additional 10% tax on the undistributed amount", "A 100% tax on the remaining undistributed amount of $200,000", "No additional tax, because the initial 30% excise tax is the only penalty"]'::jsonb, 2, 'Under IRC Section 4942, the required minimum distribution is 5% of non-charitable-use assets ($8,000,000 x 5% = $400,000). The foundation distributed only $200,000, leaving a $200,000 shortfall. The initial excise tax is 30% of the undistributed amount ($60,000). If the foundation fails to correct the underdistribution within the taxable period, an additional 100% tax is imposed on the remaining undistributed amount ($200,000). This severe penalty incentivizes timely correction.', 'medium', 3),

-- Q24: medium / L2 — Churches automatically classified as public charities
(3, 'Tax-Exempt Organizations', 'Grace Fellowship Church receives 90% of its funding from a single wealthy donor family and 10% from congregation tithes. The church has never applied for a formal IRS determination letter. Under Section 509, what is the church''s classification?', '["Private foundation, because it receives more than two-thirds of support from one source", "The church has no classification because it never applied for a determination letter", "Private operating foundation, because it operates its own programs funded by a single donor", "Public charity, because churches are automatically classified as public charities regardless of funding sources"]'::jsonb, 3, 'Under IRC Section 509(a)(1) and Section 170(b)(1)(A)(i), churches are automatically classified as public charities regardless of their funding sources. Unlike other 501(c)(3) organizations, churches are not required to meet the one-third support test or apply for formal IRS recognition. Even with concentrated donor support, a church''s classification as a public charity is based on its organizational type, not its revenue composition.', 'medium', 2),

-- Q25: easy / L1 — Private foundation presumption
(3, 'Tax-Exempt Organizations', 'Under Section 509, what is the default classification for all Section 501(c)(3) organizations?', '["Private foundation, unless the organization demonstrates it qualifies as a public charity", "Public charity, unless the organization has investment income exceeding $5,000", "Private operating foundation, unless it distributes at least 5% of assets annually", "Supporting organization, unless it operates independently of other charities"]'::jsonb, 0, 'Under IRC Section 509(a), every Section 501(c)(3) organization is presumed to be a private foundation unless it affirmatively demonstrates it qualifies as a public charity under one of the exceptions (broad public support, church, school, hospital, or supporting organization). This presumption places the burden on the organization to prove public charity status. The distinction matters because private foundations face additional excise taxes and operational restrictions under Sections 4940-4945.', 'easy', 1),

-- Q26: hard / L4 — 501(h) election dollar thresholds vs substantial part test comparison
(3, 'Tax-Exempt Organizations', 'Horizon Advocacy Institute, a 501(c)(3) public charity with exempt purpose expenditures of $800,000, spends $130,000 on lobbying in 2025 without having made a Section 501(h) election. A board member argues the organization should elect into Section 501(h). Compare how the substantial part test and the 501(h) expenditure test would evaluate these lobbying expenditures.', '["Both tests would find the lobbying excessive because $130,000 exceeds any permissible threshold", "Under the 501(h) election, lobbying of $130,000 is within the permitted ceiling of $145,000 (20% of the first $500,000 plus 15% of the next $300,000); under the substantial part test, the same amount may be deemed substantial", "The substantial part test permits up to 25% of expenditures for lobbying, so $130,000 is clearly permissible", "The 501(h) election only applies prospectively and cannot protect against lobbying expenditures already incurred"]'::jsonb, 1, 'Under IRC Section 501(h), the expenditure test provides graduated thresholds: 20% of the first $500,000 in exempt purpose expenditures ($100,000) plus 15% of the next $300,000 ($45,000), totaling $145,000. Since $130,000 is below $145,000, the organization passes under the 501(h) test. Without the election, the vague ''substantial part'' test applies, under which 16.25% of expenditures devoted to lobbying could be deemed substantial, risking loss of exempt status. The 501(h) election provides measurable certainty.', 'hard', 4),

-- Q27: medium / L2 — Failure-to-file penalty computation
(3, 'Tax-Exempt Organizations', 'Cedar Valley Education Fund, a 501(c)(3) with annual gross receipts of $180,000, files its Form 990-EZ 45 days late without reasonable cause. Under the penalty provisions, what is the total late-filing penalty?', '["$500 flat penalty for late filing", "A penalty equal to 5% of gross receipts ($9,000)", "$900, calculated as $20 per day for 45 days", "$4,500, calculated as $100 per day for 45 days"]'::jsonb, 2, 'Under IRC Section 6652(c), the penalty for late filing of Form 990 or 990-EZ is $20 per day for each day the return is late, up to the lesser of $10,500 or 5% of the organization''s gross receipts. For Cedar Valley, $20 x 45 days = $900. The $100-per-day rate applies to larger organizations with gross receipts of $1,186,000 or more. Since Cedar Valley''s gross receipts are $180,000, the $20 daily rate applies, and $900 is well below the $9,000 cap (5% x $180,000).', 'medium', 2),

-- Q28: medium / L3 — Expenditure responsibility for grants to non-501(c)(3) organizations
(3, 'Tax-Exempt Organizations', 'Cascade Foundation, a private foundation, makes a $100,000 grant to a 501(c)(4) social welfare organization to fund a community health initiative. The foundation does not exercise expenditure responsibility over the grant. How does Section 4945 classify this grant?', '["The grant is permissible because 501(c)(4) organizations are tax-exempt", "The grant is subject to the self-dealing rules under Section 4941", "The grant is permissible if the 501(c)(4) organization certifies the funds will be used for charitable purposes", "The grant is a taxable expenditure because the foundation failed to exercise expenditure responsibility over a grant to a non-501(c)(3) organization"]'::jsonb, 3, 'Under IRC Section 4945(d)(4), grants by a private foundation to organizations other than 501(c)(3) public charities are taxable expenditures unless the foundation exercises expenditure responsibility. This requires the foundation to ensure the grant is used for exempt purposes through a written agreement and regular reporting. A 501(c)(4) organization is not a 501(c)(3) charity, so expenditure responsibility is mandatory. Failure to exercise it subjects the grant to a 20% initial excise tax.', 'medium', 3),

-- Q29: hard / L4 — Section 4958 manager tax cap at $20,000
(3, 'Tax-Exempt Organizations', 'Dr. Harrison, the president of Oakridge Health Foundation (a 501(c)(3)), receives an excess benefit of $2,000,000 in compensation. Three board members (Martinez, Chen, and Phillips) each knowingly approve the transaction without obtaining comparability data. Under Section 4958, analyze the excise tax liability for each organization manager who participated.', '["Each manager owes $20,000, because the 10% tax ($200,000) is capped at $20,000 per transaction per manager", "Each manager owes $200,000, which is 10% of the excess benefit with no cap", "The three managers collectively owe $20,000, splitting the capped amount equally", "Each manager owes $50,000, which is 25% of the excess benefit divided among the three participants"]'::jsonb, 0, 'Under IRC Section 4958(a)(2), an organization manager who knowingly participates in an excess benefit transaction is subject to a 10% excise tax on the excess benefit amount. However, this tax is capped at $20,000 per transaction per manager. For a $2,000,000 excess benefit, 10% would be $200,000, but the cap limits each manager''s liability to $20,000 individually. The cap applies per manager, not collectively, so each of the three managers owes $20,000.', 'hard', 4),

-- Q30: easy / L1 — "Regularly carried on" test definition
(3, 'Tax-Exempt Organizations', 'Under the UBIT three-part test, what does ''regularly carried on'' mean?', '["The activity generates income in at least two consecutive tax years", "The activity produces gross income exceeding $1,000 annually", "The activity is conducted with a frequency and continuity comparable to similar commercial activities", "The activity is performed on a daily basis throughout the tax year"]'::jsonb, 2, 'Under IRC Section 512, an activity is ''regularly carried on'' if it is conducted with a frequency and continuity comparable to commercial activities of taxable organizations in the same line of business. A once-a-year fundraising event would generally not meet this standard, while a year-round gift shop would. The test compares the exempt organization''s activity to how similar commercial businesses operate, not to arbitrary frequency or income thresholds.', 'easy', 1)
;

COMMIT;
